//
//  ArenaText.swift
//  Actifit
//
//  Every piece of Arena copy, under Android's arena_* keys so the translations are shared
//  (Localizable.strings, generated by ci_scripts/import_android_strings.py). Kept in one file
//  so ArenaLogicTests can scan it for wagering language: entry is free, and the copy must
//  never read like gambling.
//

import Foundation

/// Translation lookup for the Arena and Friends copy. Uses the language picked in Settings, read
/// from the same place as Localizr's `localized()`, but with Foundation only so the copy can be
/// unit tested. Keys are Android's (arena_*, friends_*), so the translations are shared; a key a
/// language doesn't have yet falls back to the English given here.
enum Copy {

    /// The language code picked in Settings (where Localizr stores it), nil if none was picked.
    private static var code: String? {
        return UserDefaults.standard.string(forKey: "Localizr_current_locale")
    }

    private static var bundle: Bundle {
        if let code = code, let path = Bundle.main.path(forResource: code, ofType: "lproj"),
           let b = Bundle(path: path) { return b }
        return Bundle.main
    }

    /// So dates read in the same language as the text around them; the phone's own when no
    /// language was picked.
    static var locale: Locale {
        return code.map { Locale(identifier: $0) } ?? .current
    }

    static func text(_ key: String, _ english: String) -> String {
        return lookup(key) ?? english
    }

    /// nil when the language has no entry (NSLocalizedString would return the key itself).
    private static func lookup(_ key: String) -> String? {
        let missing = "\u{1}"
        let s = NSLocalizedString(key, tableName: nil, bundle: bundle, value: missing, comment: "")
        return s == missing ? nil : s
    }

    /// Placeholders are positional (%1$@, %2$ld), as in Android's strings, since translations
    /// may reorder them.
    static func format(_ key: String, _ english: String, _ args: CVarArg...) -> String {
        return String(format: text(key, english), arguments: args)
    }

    /// Plural forms are stored as key_one, key_other, plus key_zero/_two/_few/_many for Arabic.
    static func plural(_ key: String, _ n: Int, one: String, other: String, _ args: CVarArg...) -> String {
        // The language's form for n, else its "other" form (Korean has only that), else English.
        let pattern = lookup(key + "_" + category(n)) ?? lookup(key + "_other") ?? (n == 1 ? one : other)
        return String(format: pattern, arguments: args)
    }

    /// CLDR plural category for the current language (only Arabic needs more than one/other here).
    private static func category(_ n: Int) -> String {
        guard code?.hasPrefix("ar") == true else { return n == 1 ? "one" : "other" }
        switch n {
        case 0: return "zero"
        case 1: return "one"
        case 2: return "two"
        default:
            switch n % 100 {
            case 3...10: return "few"
            case 11...99: return "many"
            default: return "other"
            }
        }
    }
}

